S=$0;read Q;read T;read K||K=0;K=${K:-0};python3 -c 'import sys,json,os,wave,math as m;q=sys.argv[1];T=max(1,int(sys.argv[2]));k=sys.argv[3];S=sys.argv[4];J=lambda x:json.dumps(x,separators=(",",":"));C=lambda s:[w for w in("".join(c.lower()if c.isalnum()else" "for c in s).split())if w];R=C(q);W=R or["void"];qn=" ".join(R);G=sum((b+1)*257**i for i,b in enumerate(J([qn,T,k,"song"]).encode()));KV=sum((i+1)*(b+1)for i,b in enumerate(k.encode()));SR=sum((i+1)*(b+1)for i,b in enumerate(open(S,"rb").read()if os.path.exists(S)else b""))%10**18;b=min(T,10);N=(1<<(b+1))-1;M=997+G%97;F=lambda j:(G+SR*j+j*j+KV)%M;O=min((F(j),j)for j in range(N));ttl="Zero Origin %s V%s"%(W[0].title(),k);safe=lambda s:"".join(c if c.isalnum()or c in" -_"else"_"for c in s).strip()or"song";fn=safe(ttl);ly=fn+".lyrics.txt";wa=fn+".wav";mp=fn+".mp3";ce=fn+".clcert";open(ly,"w").write(ttl+"\n"+qn[:32]+"\nV"+k+" returns\n");n=8000*T;f=110+(O[1]+KV)%220;Y=b"".join(int(.35*m.sin(6.28*f*i/8000)*min(1,i/800)*min(1,(n-i)/800)*30000).to_bytes(2,"little",signed=True)for i in range(n));w=wave.open(wa,"wb");w.setparams((1,2,8000,0,"NONE",""));w.writeframes(Y);w.close();os.system("ffmpeg -y -loglevel error -i \"%s\" \"%s\" >/dev/null 2>&1"%(wa,mp));ok=int(os.path.exists(mp));V=int(len(R)>0 and O==min((F(j),j)for j in range(N))and os.path.getsize(wa)>44 and fn==safe(ttl));D={"P":"RMZANS2K","UTL":"RMZ-UTL/1","NL":"RMZ-NL/1","MATH":"RMZ-MATH/1","MML":"RMZ-MML/1","Q_RAW":q,"Q_NORM":qn,"TOKENS":R,"INTENT":"song","AX":"NL>MATH>MML>AUDIO","GRAM":"RAW TOK G OPT TITLE FILE CERT","VM":"qNL>qMath>qMML>qFile>qV>qH","VFY":"NL/G/OPT/TITLE/FN/WAV","SELF":SR,"ORIGIN":SR,"D0":1,"K":k,"BND":b,"ENUM":N,"OPT":O,"TITLE":ttl,"FN":fn,"FN_CERT":V,"L":ly,"WAV":wa,"MP3":[mp,ok],"CERT":ce,"TT":"z0;NL;TZC;NZO;MATH;MML;AUDIOC","V":V,"PCC":V,"ZE":V,"Bd":"bounded UTL;not full NL/RH"};open(ce,"w").write(J(D)+"\n");print(J({"P":D["P"],"TITLE":ttl,"MP3":mp,"V":V,"PCC":V,"ZE":V,"mp3_ok":ok,"cert":ce,"bytes":"<2048"}))' "$Q" "$T" "$K" "$S"